import React from 'react';
import { Tooltip } from '../content/Tooltip.jsx';
import { VisuallyHidden } from '../layout/VisuallyHidden.jsx';
import { Legend } from './Legend.jsx';

const PALETTE = [
  'var(--color-semantic-data-viz-series-1)',
  'var(--color-semantic-data-viz-series-2)',
  'var(--color-semantic-data-viz-series-3)',
  'var(--color-semantic-data-viz-series-4)',
  'var(--color-semantic-data-viz-series-5)',
];

/*
 * Medium re-point hooks — the fifth instance of the pattern (Table, Timeline,
 * Stat, table cells came first). A chart's furniture was sized in literals:
 * `fontSize="10"` on every axis tick and axis title. Ten pixels is right at a
 * desk and gone from the back of a room, so a chart placed on a slide arrives
 * with its axis unreadable and nothing the medium can do about it — a literal
 * has no seam.
 *
 * Each fallback IS the literal it replaces, so every existing product screen
 * renders byte-identically; a medium that knows its reading distance re-points
 * these in its own scope and the component never learns it moved.
 */
const AXIS_TICK_SIZE = 'var(--lk-chart-tick-size, 10px)';
const AXIS_TITLE_SIZE = 'var(--lk-chart-axis-title-size, 10px)';
const REFERENCE_LABEL_SIZE = 'var(--lk-chart-reference-label-size, 10px)';
const EMPTY_LABEL_SIZE = 'var(--lk-chart-empty-label-size, 12px)';
// Stroke weight is the same argument as type size: a 2px line reads as a hair
// at projection distance. Series, point and reference strokes use
// `vector-effect: non-scaling-stroke`, so the weight is in CSS pixels: without
// it the responsive viewBox shrank a 2-unit stroke to ~1.5px whenever the chart
// rendered narrower than its `width`. Series and reference lines keep their own knobs
// because they carry different weight in the argument.
const SERIES_STROKE = 'var(--lk-chart-series-stroke, 2)';
const REFERENCE_STROKE = 'var(--lk-chart-reference-stroke, 1.5)';

function isFiniteNumber(value) {
  return Number.isFinite(Number(value));
}

function normalizeSeries(series) {
  return series.map((item, index) => ({
    ...item,
    id: item.id ?? item.name ?? index,
    points: (item.points || [])
      .filter((point) => isFiniteNumber(point.x) && isFiniteNumber(point.y))
      .map((point) => ({ x: Number(point.x), y: Number(point.y) })),
  }));
}

function resolveDomain(values, explicitDomain, fallback, includeZero = false) {
  if (Array.isArray(explicitDomain) && explicitDomain.length === 2) {
    const [min, max] = explicitDomain;
    if (isFiniteNumber(min) && isFiniteNumber(max) && Number(min) !== Number(max)) {
      return [Number(min), Number(max)];
    }
  }

  if (!values.length) return fallback;

  let min = Math.min(...values);
  let max = Math.max(...values);
  if (includeZero) {
    min = Math.min(0, min);
    max = Math.max(0, max);
  }
  if (min === max) {
    const delta = Math.abs(min) || 1;
    return [min - delta * 0.5, max + delta * 0.5];
  }
  return [min, max];
}

function buildTicks(min, max, count) {
  const safeCount = Math.max(1, Math.floor(count));
  if (safeCount === 1) return [min];
  return Array.from({ length: safeCount }, (_, index) => min + ((max - min) * index) / (safeCount - 1));
}

/*
 * Nice y ticks. Splitting the raw data range into equal parts produced labels
 * such as 0 / 0.22 / 0.45 / 0.67 / 0.89 that nobody can read against a grid.
 * The step is snapped to the nearest (geometric) member of 1 · 2 · 2.5 · 5 ×
 * 10^n — 2.5 is kept so a 0–1 or 0–100 percent axis still reads 0/25/50/75/100.
 * An automatic domain is widened to whole steps; an explicit domain is the
 * host's decision and keeps its bounds, with ticks placed on step multiples
 * inside it (d3 `ticks` behavior).
 */
const NICE_STEPS = [1, 2, 2.5, 5, 10];

function stepCandidates(span, count) {
  const raw = span / Math.max(1, count);
  const power = 10 ** Math.floor(Math.log10(raw));
  const error = raw / power;
  const index = NICE_STEPS.reduce((best, candidate, candidateIndex) => (
    Math.abs(Math.log(error / candidate)) < Math.abs(Math.log(error / NICE_STEPS[best])) ? candidateIndex : best
  ), 0);
  // The nearest nice step, then the next one up: widening an automatic domain
  // to whole steps can add an interval, and the larger step may land closer to
  // the requested count.
  return [index, Math.min(index + 1, NICE_STEPS.length - 1)].map((candidateIndex) => {
    const multiplier = NICE_STEPS[candidateIndex];
    const step = multiplier * power;
    const decimals = Math.max(0, -Math.floor(Math.log10(step) + 1e-9) + (multiplier === 2.5 ? 1 : 0));
    return { step, decimals };
  });
}

function ticksForStep(min, max, { step, decimals }, expand) {
  // Ticks are integer multiples of the step rounded to its precision, so labels
  // never carry float noise such as 0.30000000000000004.
  const clean = (value) => Number(value.toFixed(decimals));
  const epsilon = step * 1e-6;
  const domain = expand
    ? [clean(Math.floor((min + epsilon) / step) * step), clean(Math.ceil((max - epsilon) / step) * step)]
    : [min, max];
  const first = Math.ceil((domain[0] - epsilon) / step);
  const last = Math.floor((domain[1] + epsilon) / step);
  const ticks = [];
  for (let index = first; index <= last; index += 1) ticks.push(clean(index * step));
  return { domain, ticks };
}

function niceTicks(min, max, count, expand) {
  if (!(max > min)) return { domain: [min, max], ticks: [min] };
  return stepCandidates(max - min, count)
    .map((candidate) => ticksForStep(min, max, candidate, expand))
    .reduce((best, option) => (
      Math.abs(option.ticks.length - 1 - count) < Math.abs(best.ticks.length - 1 - count) ? option : best
    ));
}

function hasExplicitDomain(domain) {
  return Array.isArray(domain) && domain.length === 2
    && isFiniteNumber(domain[0]) && isFiniteNumber(domain[1]) && Number(domain[0]) !== Number(domain[1]);
}

// Rough advance width at the reference-label size, used only to reserve right
// padding so a label placed past the line end is not clipped.
function estimateLabelWidth(text) {
  return [...text].reduce((width, char) => width + (char.charCodeAt(0) > 0x1100 ? 10 : 6), 0);
}

function resolveTickValues(min, max, ticks, fallbackCount) {
  if (Array.isArray(ticks)) {
    const values = ticks.filter(isFiniteNumber).map(Number);
    return values.length ? values : buildTicks(min, max, fallbackCount);
  }
  return buildTicks(min, max, ticks ?? fallbackCount);
}

function linePath(points, sx, sy) {
  return points
    .map((point, index) => `${index === 0 ? 'M' : 'L'}${sx(point.x).toFixed(2)} ${sy(point.y).toFixed(2)}`)
    .join(' ');
}

function defaultFormatY(value) {
  return Math.abs(value) >= 100 ? Math.round(value) : Math.round(value * 100) / 100;
}

function defaultFormatX(value) {
  return `${value}`;
}

function nodeText(node) {
  if (typeof node === 'string' || typeof node === 'number') return String(node);
  if (Array.isArray(node)) return node.map(nodeText).filter(Boolean).join(' ');
  if (React.isValidElement(node)) return nodeText(node.props.children);
  return '';
}

function joinIds(...ids) {
  return ids.filter(Boolean).join(' ') || undefined;
}

function formattedText(formatter, value) {
  return nodeText(formatter(value)) || `${value}`;
}

/**
 * LDS Product Data — LineChart
 * Multi-series SVG line chart for training curves and telemetry trends. It stays
 * presentational: host code owns data, formatters, and domain decisions.
 */
export function LineChart({
  series = [],
  width = 520,
  height = 240,
  xLabel,
  yLabel,
  xTicks = 2,
  yTicks = 4,
  xDomain,
  yDomain,
  includeZero = true,
  showGrid = true,
  showLegend = true,
  showPoints = false,
  showTooltip = false,
  tooltipXValues,
  renderTooltip,
  referenceLines = [],
  emptyLabel = '데이터가 없습니다.',
  formatX,
  formatY,
  description,
  summary,
  style,
  'aria-label': ariaLabel,
  'aria-describedby': ariaDescribedBy,
  ...rest
}) {
  const normalized = normalizeSeries(series);
  const allPoints = normalized.flatMap((item) => item.points);
  const chartWidth = Math.max(160, Number(width) || 520);
  const chartHeight = Math.max(120, Number(height) || 240);
  const [xMin, xMax] = resolveDomain(allPoints.map((point) => point.x), xDomain, [0, 1]);
  const [rawYMin, rawYMax] = resolveDomain(allPoints.map((point) => point.y), yDomain, [0, 1], includeZero);
  const yScale = niceTicks(rawYMin, rawYMax, Math.max(1, Number(yTicks) || 4), !hasExplicitDomain(yDomain));
  const [yMin, yMax] = yScale.domain;
  const yTickValues = yScale.ticks;
  const xTickValues = resolveTickValues(xMin, xMax, xTicks, 2);
  const visibleReferenceLines = referenceLines
    .filter((line) => isFiniteNumber(line.y) && Number(line.y) >= yMin && Number(line.y) <= yMax);
  // Reference labels sit past the right end of their line, outside the plot,
  // so they never sit on top of a series; reserve room for the widest one.
  const referenceLabelWidth = visibleReferenceLines.reduce(
    (width, line) => Math.max(width, line.label != null ? estimateLabelWidth(nodeText(line.label)) + 8 : 0), 0);
  // The x-axis title is drawn inside the SVG, right-aligned under the last tick.
  const pad = { top: 14, right: Math.max(22, referenceLabelWidth), bottom: xLabel ? 36 : 24, left: 46 };
  const innerWidth = Math.max(1, chartWidth - pad.left - pad.right);
  const innerHeight = Math.max(1, chartHeight - pad.top - pad.bottom);
  const sx = (x) => pad.left + ((x - xMin) / (xMax - xMin)) * innerWidth;
  const sy = (y) => pad.top + innerHeight - ((y - yMin) / (yMax - yMin)) * innerHeight;
  const fx = formatX || defaultFormatX;
  const fy = formatY || defaultFormatY;
  const hasData = allPoints.length > 0;
  const values = [...new Set((tooltipXValues ?? allPoints.map((point) => point.x)).filter(Number.isFinite))].sort((a, b) => a - b);
  const [activeX, setActiveX] = React.useState(null);
  const [tooltipVisible, setTooltipVisible] = React.useState(false);
  const selectedX = values.includes(activeX) ? activeX : values.at(-1);
  const pointsAtSelectedX = normalized.flatMap((item) => item.points.filter((point) => point.x === selectedX));
  const selectedY = pointsAtSelectedX.length
    ? pointsAtSelectedX.reduce((sum, point) => sum + point.y, 0) / pointsAtSelectedX.length
    : (yMin + yMax) / 2;
  const [tooltipAnchor, setTooltipAnchor] = React.useState(null);
  const resolvedTooltipAnchor = tooltipAnchor ?? {
    x: sx(selectedX ?? xMax),
    y: sy(selectedY),
  };
  const tooltipEnabled = showTooltip && values.length > 0;
  const selectPointer = (event) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    const chartX = (event.clientX - bounds.left) * chartWidth / bounds.width;
    const chartY = (event.clientY - bounds.top) * chartHeight / bounds.height;
    const x = xMin + ((chartX - pad.left) / innerWidth) * (xMax - xMin);
    setActiveX(values.reduce((nearest, value) => Math.abs(value - x) < Math.abs(nearest - x) ? value : nearest, values[0]));
    setTooltipAnchor({
      x: Math.min(pad.left + innerWidth, Math.max(pad.left, chartX)),
      y: Math.min(pad.top + innerHeight, Math.max(pad.top, chartY)),
    });
    setTooltipVisible(true);
  };
  const selectKeyboard = (event) => {
    const index = values.indexOf(selectedX);
    const next = event.key === 'ArrowLeft' ? Math.max(0, index - 1)
      : event.key === 'ArrowRight' ? Math.min(values.length - 1, index + 1)
      : event.key === 'Home' ? 0 : event.key === 'End' ? values.length - 1 : null;
    if (next !== null) {
      event.preventDefault();
      const nextX = values[next];
      const points = normalized.flatMap((item) => item.points.filter((point) => point.x === nextX));
      const nextY = points.length ? points.reduce((sum, point) => sum + point.y, 0) / points.length : (yMin + yMax) / 2;
      setActiveX(nextX);
      setTooltipAnchor({ x: sx(nextX), y: sy(nextY) });
      setTooltipVisible(true);
    } else if (event.key === 'Escape') {
      setTooltipVisible(false);
    }
  };
  const rawId = React.useId();
  const clipId = `line-chart-${rawId.replace(/:/g, '')}-clip`;
  const descriptionId = `${rawId}-description`;
  const summaryId = `${rawId}-summary`;
  const chartLabel = ariaLabel || (yLabel ? `${yLabel} 라인 차트` : '라인 차트');
  const emptyText = nodeText(emptyLabel) || '데이터가 없습니다.';
  /* Reference lines are threshold annotations, not decoration: they only exist
     inside the `role="img"` SVG, so screen-reader users never learn the
     threshold — nor which series crossed it — unless the text alternative says
     so. Same rule Carbon/Highcharts apply to annotations. */
  const referenceSummary = visibleReferenceLines
    .map((line, index) => {
      const y = Number(line.y);
      const name = nodeText(line.label) || `기준선 ${index + 1}`;
      const crossed = normalized
        .filter((item) => item.points.some((point) => point.y > y))
        .map((item, itemIndex) => item.accessibleLabel || nodeText(item.name) || `시리즈 ${itemIndex + 1}`);
      return `${name} ${formattedText(fy, y)}: ${crossed.length ? `${crossed.join(', ')} 초과` : '초과한 시리즈 없음'}.`;
    })
    .join(' ');
  const automaticSummary = hasData
    ? normalized.map((item, index) => {
      const label = item.accessibleLabel || nodeText(item.name) || `시리즈 ${index + 1}`;
      if (!item.points.length) return `${label}: ${emptyText}.`;
      const first = item.points[0];
      const last = item.points[item.points.length - 1];
      const minimum = item.points.reduce((current, point) => (point.y < current.y ? point : current), first);
      const maximum = item.points.reduce((current, point) => (point.y > current.y ? point : current), first);
      return `${label}: ${item.points.length}개 점. 시작 ${formattedText(fx, first.x)}에서 ${formattedText(fy, first.y)}, 최저 ${formattedText(fy, minimum.y)}, 최고 ${formattedText(fy, maximum.y)}, 마지막 ${formattedText(fx, last.x)}에서 ${formattedText(fy, last.y)}.`;
    }).concat(referenceSummary ? [`기준선 ${visibleReferenceLines.length}개. ${referenceSummary}`] : []).join(' ')
    : emptyText;
  const resolvedSummary = summary ?? automaticSummary;
  const legendItems = normalized.map((item, index) => ({
    id: item.id,
    label: item.name ?? `시리즈 ${index + 1}`,
    color: item.color || PALETTE[index % PALETTE.length],
    shape: 'line',
    dashed: item.dashed,
    disabled: item.points.length === 0,
  }));

  return (
    <div
      style={{
        display: 'grid',
        gap: 'var(--space-2)',
        width: '100%',
        maxWidth: chartWidth,
        minWidth: 0,
        fontFamily: 'var(--font-sans)',
        ...style,
      }}
      {...rest}
    >
      {description != null && <VisuallyHidden id={descriptionId}>{description}</VisuallyHidden>}
      {resolvedSummary != null && <VisuallyHidden id={summaryId} data-chart-summary>{resolvedSummary}</VisuallyHidden>}
      {/* The legend reads before the plot, aligned with the plot's left edge.
          The inset is a percentage of the viewBox width so it stays aligned
          when the responsive SVG shrinks. */}
      {showLegend && normalized.length > 0 && (
        <Legend
          items={legendItems}
          size="sm"
          aria-label="라인 차트 범례"
          style={{ paddingLeft: `${(pad.left / chartWidth) * 100}%`, maxWidth: '100%' }}
        />
      )}
      <ChartTooltip enabled={tooltipEnabled} open={tooltipVisible} anchor={resolvedTooltipAnchor} onOpenChange={setTooltipVisible} content={!tooltipEnabled ? null : renderTooltip ? renderTooltip(selectedX) : (
        <span style={{ display: 'grid', gap: 'var(--space-1)' }}>
          <strong>{fx(selectedX)}</strong>
          {normalized.flatMap((item) => item.points.filter((point) => point.x === selectedX).map((point) => (
            <span key={item.id}>{item.name}: {fy(point.y)}{yLabel ? ` ${yLabel}` : ''}</span>
          )))}
        </span>
      )}>
      <svg
        viewBox={`0 0 ${chartWidth} ${chartHeight}`}
        role="img"
        aria-label={chartLabel}
        aria-describedby={joinIds(ariaDescribedBy, description != null && descriptionId, resolvedSummary != null && summaryId)}
        data-chart-type="line"
        tabIndex={tooltipEnabled ? 0 : undefined}
        onPointerMove={tooltipEnabled ? selectPointer : undefined}
        onPointerDown={tooltipEnabled ? (event) => { selectPointer(event); event.currentTarget.focus(); } : undefined}
        onFocus={tooltipEnabled ? () => setTooltipVisible(true) : undefined}
        onBlur={tooltipEnabled ? () => setTooltipVisible(false) : undefined}
        onKeyDown={tooltipEnabled ? selectKeyboard : undefined}
        style={{
          display: 'block',
          width: '100%',
          height: 'auto',
          aspectRatio: `${chartWidth} / ${chartHeight}`,
          overflow: 'visible',
        }}
      >
        <defs>
          <clipPath id={clipId}>
            <rect x={pad.left} y={pad.top} width={innerWidth} height={innerHeight} />
          </clipPath>
        </defs>

        {showGrid &&
          yTickValues.map((tick) => (
            <line
              key={`grid-${tick}`}
              x1={pad.left}
              y1={sy(tick)}
              x2={pad.left + innerWidth}
              y2={sy(tick)}
              stroke="var(--color-semantic-line-normal-alternative)"
              strokeWidth="1"
            />
          ))}

        <line
          x1={pad.left}
          y1={pad.top}
          x2={pad.left}
          y2={pad.top + innerHeight}
          stroke="var(--color-semantic-line-normal-normal)"
          strokeWidth="1"
        />
        <line
          x1={pad.left}
          y1={pad.top + innerHeight}
          x2={pad.left + innerWidth}
          y2={pad.top + innerHeight}
          stroke="var(--color-semantic-line-normal-normal)"
          strokeWidth="1"
        />

        {yTickValues.map((tick) => (
          <text
            key={`y-${tick}`}
            x={pad.left - 8}
            y={sy(tick) + 3}
            textAnchor="end"
            fill="var(--color-semantic-label-alternative)"
            style={{ fontSize: AXIS_TICK_SIZE, fontVariantNumeric: 'tabular-nums' }}
          >
            {fy(tick)}
          </text>
        ))}

        {xTickValues.map((tick, index) => (
          <text
            key={`x-${tick}`}
            x={sx(tick)}
            y={pad.top + innerHeight + 16}
            textAnchor={index === 0 ? 'start' : index === xTickValues.length - 1 ? 'end' : 'middle'}
            fill="var(--color-semantic-label-alternative)"
            style={{ fontSize: AXIS_TICK_SIZE, fontVariantNumeric: 'tabular-nums' }}
          >
            {fx(tick)}
          </text>
        ))}

        {xLabel && (
          <text
            x={pad.left + innerWidth}
            y={pad.top + innerHeight + 31}
            textAnchor="end"
            fontWeight="var(--fw-semibold)"
            fill="var(--color-semantic-label-alternative)"
            style={{ fontSize: AXIS_TITLE_SIZE }}
          >
            {xLabel}
          </text>
        )}

        {yLabel && (
          <text
            x={14}
            y={pad.top + innerHeight / 2}
            transform={`rotate(-90 14 ${pad.top + innerHeight / 2})`}
            textAnchor="middle"
            fontWeight="var(--fw-semibold)"
            fill="var(--color-semantic-label-alternative)"
            style={{ fontSize: AXIS_TITLE_SIZE }}
          >
            {yLabel}
          </text>
        )}

        {visibleReferenceLines
          .map((line, index) => {
            const y = sy(Number(line.y));
            const color = line.color || 'var(--color-semantic-data-viz-series-5)';
            return (
              <g key={line.id ?? line.label ?? index}>
                <line
                  x1={pad.left}
                  y1={y}
                  x2={pad.left + innerWidth}
                  y2={y}
                  stroke={color}
                  style={{ strokeWidth: REFERENCE_STROKE }}
                  vectorEffect="non-scaling-stroke"
                  strokeDasharray={line.dashed === false ? undefined : '4 4'}
                />
                {line.label != null && (
                  <text
                    x={pad.left + innerWidth + 4}
                    y={y}
                    textAnchor="start"
                    dominantBaseline="middle"
                    fontWeight="var(--fw-semibold)"
                    fill={color}
                    style={{ fontSize: REFERENCE_LABEL_SIZE }}
                  >
                    {line.label}
                  </text>
                )}
              </g>
            );
          })}

        <g clipPath={`url(#${clipId})`}>
          {tooltipEnabled && tooltipVisible && (
            <line x1={sx(selectedX)} x2={sx(selectedX)} y1={pad.top} y2={pad.top + innerHeight}
              stroke="var(--color-semantic-label-alternative)" strokeDasharray="4 4" />
          )}
          {normalized.map((item, index) => {
            const color = item.color || PALETTE[index % PALETTE.length];
            const path = linePath(item.points, sx, sy);

            return (
              <g key={item.id}>
                {item.points.length > 1 && (
                  <path
                    d={path}
                    fill="none"
                    stroke={color}
                    style={{ strokeWidth: SERIES_STROKE }}
                    vectorEffect="non-scaling-stroke"
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    strokeDasharray={item.dashed ? '5 4' : undefined}
                  />
                )}
                {(showPoints || item.points.length === 1) &&
                  item.points.map((point, pointIndex) => (
                    <circle
                      key={`${item.id}-${pointIndex}`}
                      cx={sx(point.x)}
                      cy={sy(point.y)}
                      r="3"
                      fill="var(--color-semantic-background-elevated-normal)"
                      stroke={color}
                      style={{ strokeWidth: SERIES_STROKE }}
                      vectorEffect="non-scaling-stroke"
                    />
                  ))}
              </g>
            );
          })}
        </g>

        {!hasData && (
          <text
            data-chart-empty
            x={pad.left + innerWidth / 2}
            y={pad.top + innerHeight / 2}
            textAnchor="middle"
            dominantBaseline="middle"
            fontWeight="var(--fw-medium)"
            fill="var(--color-semantic-label-alternative)"
            style={{ fontSize: EMPTY_LABEL_SIZE }}
          >
            {emptyLabel}
          </text>
        )}
      </svg>
      </ChartTooltip>

    </div>
  );
}

function ChartTooltip({ enabled, open, anchor, content, children, onOpenChange }) {
  if (!enabled) return children;
  return (
    <span
      style={{ position: 'relative', display: 'block', width: '100%' }}
      onPointerLeave={(event) => {
        if (!event.currentTarget.contains(event.currentTarget.ownerDocument.activeElement)) onOpenChange(false);
      }}
    >
      {children}
      <Tooltip content={content} open={open} onOpenChange={onOpenChange} delay={{ open: 0, close: 150 }} withinPortal={false}
        styles={{
          root: { position: 'absolute', left: anchor.x, top: anchor.y, width: 1, height: 1 },
          bubble: { pointerEvents: 'auto' },
        }}>
        <span aria-hidden="true" style={{ display: 'block', width: 1, height: 1 }} />
      </Tooltip>
    </span>
  );
}
